import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';

const Onboarding = () => {
  const { completeOnboarding, currentUser } = useAuth();
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  
  const [userPreferences, setUserPreferences] = useState({
    school: '',
    major: '',
    year: '',
    interests: [],
    bio: '',
    studyGoals: {
      dailyHours: 0,
      weeklyTasks: 0
    }
  });
  
  // Available interests for selection
  const interestOptions = [
    'Computer Science', 'Mathematics', 'Physics', 'Chemistry', 'Biology',
    'Engineering', 'Literature', 'History', 'Art', 'Music', 'Languages',
    'Economics', 'Business', 'Psychology', 'Philosophy', 'Sociology'
  ];
  
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    
    if (name.includes('.')) {
      const [parent, child] = name.split('.');
      setUserPreferences({
        ...userPreferences,
        [parent]: {
          ...userPreferences[parent],
          [child]: value
        }
      });
    } else {
      setUserPreferences({
        ...userPreferences,
        [name]: value
      });
    }
  };
  
  const handleInterestToggle = (interest) => {
    const currentInterests = [...userPreferences.interests];
    
    if (currentInterests.includes(interest)) {
      const updatedInterests = currentInterests.filter(i => i !== interest);
      setUserPreferences({
        ...userPreferences,
        interests: updatedInterests
      });
    } else {
      setUserPreferences({
        ...userPreferences,
        interests: [...currentInterests, interest]
      });
    }
  };
  
  const handleSubmit = async () => {
    setIsLoading(true);
    
    try {
      const success = completeOnboarding(userPreferences);
      
      if (success) {
        navigate('/dashboard');
      }
    } catch (error) {
      console.error('Error completing onboarding:', error);
    } finally {
      setIsLoading(false);
    }
  };
  
  const nextStep = () => {
    setCurrentStep(prev => Math.min(prev + 1, 3));
  };
  
  const prevStep = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
  };
  
  return (
    <div className="relative flex flex-col items-center justify-center min-h-screen p-4 overflow-hidden bg-neural-dark">
      {/* Background effect */}
      <div className="absolute inset-0 neural-network-bg">
        {Array.from({ length: 15 }).map((_, i) => (
          <motion.circle
            key={i}
            r={Math.random() * 3 + 1}
            fill="rgba(100, 200, 255, 0.3)"
            cx={`${Math.random() * 100}%`}
            cy={`${Math.random() * 100}%`}
            initial={{ opacity: 0.1 }}
            animate={{ 
              opacity: [0.1, 0.3, 0.1],
              scale: [1, 1.2, 1],
            }}
            transition={{ 
              duration: Math.random() * 3 + 2,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        ))}
      </div>

      {/* Content card */}
      <motion.div 
        className="neural-card w-full max-w-2xl p-6 z-10"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="text-center mb-8">
          <motion.h1 
            className="text-3xl font-bold neural-text-gradient"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.8 }}
          >
            Let's Set Up Your Experience
          </motion.h1>
          <motion.p 
            className="mt-2 text-white/70"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3, duration: 0.8 }}
          >
            {currentUser && currentUser.name ? `Welcome, ${currentUser.name}!` : 'Welcome!'} Tell us a bit about yourself
          </motion.p>
        </div>
        
        {/* Progress indicators */}
        <div className="flex justify-center mb-8">
          {[1, 2, 3].map(step => (
            <div 
              key={step} 
              className={`w-3 h-3 rounded-full mx-2 ${
                step === currentStep 
                  ? 'bg-dendrite-primary' 
                  : step < currentStep 
                    ? 'bg-dendrite-base' 
                    : 'bg-gray-700'
              }`}
            />
          ))}
        </div>
        
        {/* Step 1: Academic Information */}
        {currentStep === 1 && (
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
          >
            <h2 className="text-xl font-bold mb-4 text-white/90">Academic Information</h2>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="school" className="block mb-2 text-sm font-medium text-white/80">
                  School or University
                </label>
                <input
                  type="text"
                  id="school"
                  name="school"
                  className="neural-input w-full text-white/90"
                  placeholder="Enter your school or university"
                  value={userPreferences.school}
                  onChange={handleInputChange}
                />
              </div>
              
              <div>
                <label htmlFor="major" className="block mb-2 text-sm font-medium text-white/80">
                  Field of Study / Major
                </label>
                <input
                  type="text"
                  id="major"
                  name="major"
                  className="neural-input w-full text-white/90"
                  placeholder="Enter your major or field of study"
                  value={userPreferences.major}
                  onChange={handleInputChange}
                />
              </div>
              
              <div>
                <label htmlFor="year" className="block mb-2 text-sm font-medium text-white/80">
                  Year / Level
                </label>
                <select
                  id="year"
                  name="year"
                  className="neural-input w-full text-white/90"
                  value={userPreferences.year}
                  onChange={handleInputChange}
                >
                  <option value="">Select your year</option>
                  <option value="1st Year">1st Year</option>
                  <option value="2nd Year">2nd Year</option>
                  <option value="3rd Year">3rd Year</option>
                  <option value="4th Year">4th Year</option>
                  <option value="5th Year">5th Year</option>
                  <option value="Graduate">Graduate Student</option>
                  <option value="Other">Other</option>
                </select>
              </div>
            </div>
          </motion.div>
        )}
        
        {/* Step 2: Interests */}
        {currentStep === 2 && (
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
          >
            <h2 className="text-xl font-bold mb-4 text-white/90">Your Interests</h2>
            <p className="text-white/70 mb-4">Select topics that interest you</p>
            
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-6">
              {interestOptions.map(interest => (
                <motion.div
                  key={interest}
                  className={`p-3 rounded-lg cursor-pointer text-center text-sm transition-colors ${
                    userPreferences.interests.includes(interest)
                      ? 'bg-dendrite-primary/30 border border-dendrite-base text-white'
                      : 'bg-gray-800/50 border border-gray-700/50 text-white/70 hover:bg-gray-700/50'
                  }`}
                  whileHover={{ scale: 1.03 }}
                  whileTap={{ scale: 0.97 }}
                  onClick={() => handleInterestToggle(interest)}
                >
                  {interest}
                </motion.div>
              ))}
            </div>
            
            <div>
              <label htmlFor="bio" className="block mb-2 text-sm font-medium text-white/80">
                Short Bio (Optional)
              </label>
              <textarea
                id="bio"
                name="bio"
                rows="4"
                className="neural-input w-full text-white/90"
                placeholder="Tell us a bit about yourself..."
                value={userPreferences.bio}
                onChange={handleInputChange}
              ></textarea>
            </div>
          </motion.div>
        )}
        
        {/* Step 3: Study Goals */}
        {currentStep === 3 && (
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
          >
            <h2 className="text-xl font-bold mb-4 text-white/90">Study Goals</h2>
            <p className="text-white/70 mb-4">Set your study targets to track progress</p>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="dailyHours" className="block mb-2 text-sm font-medium text-white/80">
                  Daily Study Hours Target
                </label>
                <input
                  type="number"
                  id="dailyHours"
                  name="studyGoals.dailyHours"
                  min="0"
                  max="24"
                  className="neural-input w-full text-white/90"
                  placeholder="Hours per day"
                  value={userPreferences.studyGoals.dailyHours}
                  onChange={handleInputChange}
                />
              </div>
              
              <div>
                <label htmlFor="weeklyTasks" className="block mb-2 text-sm font-medium text-white/80">
                  Weekly Tasks Target
                </label>
                <input
                  type="number"
                  id="weeklyTasks"
                  name="studyGoals.weeklyTasks"
                  min="0"
                  className="neural-input w-full text-white/90"
                  placeholder="Tasks per week"
                  value={userPreferences.studyGoals.weeklyTasks}
                  onChange={handleInputChange}
                />
              </div>
            </div>
          </motion.div>
        )}
        
        {/* Navigation buttons */}
        <div className="flex justify-between mt-8">
          {currentStep > 1 ? (
            <motion.button
              className="px-5 py-2.5 bg-gray-800 border border-gray-700 rounded-lg text-white/80"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={prevStep}
            >
              Back
            </motion.button>
          ) : (
            <div></div> // Empty div for alignment
          )}
          
          {currentStep < 3 ? (
            <motion.button
              className="px-5 py-2.5 bg-dendrite-primary/20 border border-dendrite-base rounded-lg text-white"
              whileHover={{ 
                scale: 1.05,
                boxShadow: '0 0 15px rgba(100, 200, 255, 0.5)' 
              }}
              whileTap={{ scale: 0.95 }}
              onClick={nextStep}
            >
              Next
            </motion.button>
          ) : (
            <motion.button
              className="px-5 py-2.5 bg-dendrite-primary/20 border border-dendrite-base rounded-lg text-white"
              whileHover={{ 
                scale: 1.05,
                boxShadow: '0 0 15px rgba(100, 200, 255, 0.5)' 
              }}
              whileTap={{ scale: 0.95 }}
              onClick={handleSubmit}
              disabled={isLoading}
            >
              {isLoading ? (
                <span className="flex items-center">
                  <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Setting Up...
                </span>
              ) : (
                "Complete Setup"
              )}
            </motion.button>
          )}
        </div>
      </motion.div>
    </div>
  );
};

export default Onboarding; 